import * as jspb from 'google-protobuf'

import * as ast_pc_pb from '../ast/pc_pb';
import * as virt_html_pb from '../virt/html_pb';
import * as virt_css_pb from '../virt/css_pb';


export class FileRequest extends jspb.Message {
  getPath(): string;
  setPath(value: string): FileRequest;

  serializeBinary(): Uint8Array;
  toObject(includeInstance?: boolean): FileRequest.AsObject;
  static toObject(includeInstance: boolean, msg: FileRequest): FileRequest.AsObject;
  static serializeBinaryToWriter(message: FileRequest, writer: jspb.BinaryWriter): void;
  static deserializeBinary(bytes: Uint8Array): FileRequest;
  static deserializeBinaryFromReader(message: FileRequest, reader: jspb.BinaryReader): FileRequest;
}

export namespace FileRequest {
  export type AsObject = {
    path: string,
  }
}

export class FileResponse extends jspb.Message {
  getRawContent(): Uint8Array | string;
  getRawContent_asU8(): Uint8Array;
  getRawContent_asB64(): string;
  setRawContent(value: Uint8Array | string): FileResponse;

  getPaperclip(): PaperclipData | undefined;
  setPaperclip(value?: PaperclipData): FileResponse;
  hasPaperclip(): boolean;
  clearPaperclip(): FileResponse;

  getDataCase(): FileResponse.DataCase;

  serializeBinary(): Uint8Array;
  toObject(includeInstance?: boolean): FileResponse.AsObject;
  static toObject(includeInstance: boolean, msg: FileResponse): FileResponse.AsObject;
  static serializeBinaryToWriter(message: FileResponse, writer: jspb.BinaryWriter): void;
  static deserializeBinary(bytes: Uint8Array): FileResponse;
  static deserializeBinaryFromReader(message: FileResponse, reader: jspb.BinaryReader): FileResponse;
}

export namespace FileResponse {
  export type AsObject = {
    rawContent: Uint8Array | string,
    paperclip?: PaperclipData.AsObject,
  }

  export enum DataCase { 
    DATA_NOT_SET = 0,
    PAPERCLIP = 2,
  }
}

export class PaperclipData extends jspb.Message {
  getCss(): virt_css_pb.Document | undefined;
  setCss(value?: virt_css_pb.Document): PaperclipData;
  hasCss(): boolean;
  clearCss(): PaperclipData;

  getHtml(): virt_html_pb.Document | undefined;
  setHtml(value?: virt_html_pb.Document): PaperclipData;
  hasHtml(): boolean;
  clearHtml(): PaperclipData;

  serializeBinary(): Uint8Array;
  toObject(includeInstance?: boolean): PaperclipData.AsObject;
  static toObject(includeInstance: boolean, msg: PaperclipData): PaperclipData.AsObject;
  static serializeBinaryToWriter(message: PaperclipData, writer: jspb.BinaryWriter): void;
  static deserializeBinary(bytes: Uint8Array): PaperclipData;
  static deserializeBinaryFromReader(message: PaperclipData, reader: jspb.BinaryReader): PaperclipData;
}

export namespace PaperclipData {
  export type AsObject = {
    css?: virt_css_pb.Document.AsObject,
    html?: virt_html_pb.Document.AsObject,
  }
}

